#include <iostream>
using namespace std;

struct Node {
    int key;
    Node* left;
    Node* right;
};

Node* insert(Node* root, int key) {
    if (root == nullptr) {
        return new Node{key, nullptr, nullptr};
    }
    if (key < root->key) {
        root->left = insert(root->left, key);
    } else {
        root->right = insert(root->right, key);
    }
    return root;
}

void inorder(const Node* node) {
    if (node == nullptr) {
        return;
    }
    inorder(node->left);
    cout << node->key << " ";
    inorder(node->right);
}

void destroy(Node* node) {
    if (node == nullptr) {
        return;
    }
    destroy(node->left);
    destroy(node->right);
    delete node;
}

int main() {
    Node* root = nullptr;
    for (int k : {5, 3, 8, 1, 4}) {
        root = insert(root, k);
    }
    inorder(root);
    cout << endl;
    destroy(root);
    return 0;
}

#include <algorithm>
#include <iostream>
using namespace std;

struct Node {
    int key;
    Node* left;
    Node* right;
};

Node* insert(Node* root, int key) {
    if (root == nullptr) {
        return new Node{key, nullptr, nullptr};
    }
    if (key < root->key) {
        root->left = insert(root->left, key);
    } else {
        root->right = insert(root->right, key);
    }
    return root;
}

bool contains(const Node* node, int key) {
    if (node == nullptr) {
        return false;
    }
    if (key == node->key) {
        return true;
    }
    return key < node->key ? contains(node->left, key) : contains(node->right, key);
}

int height(const Node* node) {
    if (node == nullptr) {
        return 0;
    }
    return 1 + max(height(node->left), height(node->right));
}

void destroy(Node* node) {
    if (node == nullptr) {
        return;
    }
    destroy(node->left);
    destroy(node->right);
    delete node;
}

int main() {
    Node* root = nullptr;
    for (int k : {5, 3, 8, 1, 4}) {
        root = insert(root, k);
    }
    cout << boolalpha << contains(root, 4) << endl;
    cout << contains(root, 7) << endl;
    cout << height(root) << endl;
    destroy(root);
    return 0;
}

